DO $$
DECLARE
    total integer;
BEGIN
    SELECT count(*) INTO total FROM clientes;
    RAISE NOTICE 'Hay % clientes', total;
END
$$;

DO $$
DECLARE
    c clientes%ROWTYPE;
BEGIN
    SELECT * INTO c FROM clientes WHERE id = 1;
    IF FOUND THEN
        RAISE NOTICE 'Cliente: %', c.nombre;
    END IF;
END
$$;

DO $$
DECLARE
    precio numeric := 45;
BEGIN
    IF precio < 30 THEN
        RAISE NOTICE 'barato';
    ELSIF precio < 80 THEN
        RAISE NOTICE 'medio';
    ELSE
        RAISE NOTICE 'caro';
    END IF;
END
$$;

