CREATE OR REPLACE FUNCTION precio_con_iva(p numeric) RETURNS numeric
LANGUAGE sql
AS $$
    SELECT round(p * 1.13, 2);
$$;

SELECT nombre, precio_con_iva(precio) FROM productos;
DROP FUNCTION precio_con_iva(numeric);

CREATE OR REPLACE PROCEDURE subir_precios(porcentaje numeric)
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE productos SET precio = round(precio * (1 + porcentaje / 100), 2);
    RAISE NOTICE 'Precios actualizados';
END
$$;

DROP PROCEDURE subir_precios(numeric);

CREATE OR REPLACE FUNCTION tg_nombre_mayuscula() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.nombre := initcap(NEW.nombre);
    RETURN NEW;
END
$$;

CREATE TRIGGER tr_clientes_nombre
BEFORE INSERT OR UPDATE ON clientes
FOR EACH ROW EXECUTE FUNCTION tg_nombre_mayuscula();

DROP TRIGGER tr_clientes_nombre ON clientes;
DROP FUNCTION tg_nombre_mayuscula();
